<?php require __DIR__.'/../includes/app.php';need('Customer');$c=me();$id=$c['customer_id'];head('My dashboard');
echo '<div class="card mb-4 p-4" style="background:var(--ink);color:#fff"><h4>Welcome, '.e($c['first_name']).'</h4><p class="mb-3 opacity-75">Choose a car, review your agreement, pay and sign, all online.</p><div><a class="btn btn-accent" href="cars.php"><i class="bi bi-car-front"></i> Rent a car</a></div></div>';
tiles([['cars.php','Rent a car','car-front'],['my.php?tab=res','My reservations','calendar-check'],['my.php?tab=inv','My invoices','receipt'],['my.php?tab=pay','My payments','credit-card']]);$todo=q("SELECT a.agreement_id,a.agreement_number,i.invoice_number,i.status invoice_status FROM rental_agreements a LEFT JOIN invoices i USING(reservation_id) WHERE a.customer_id=? AND a.status IN('draft','issued')",[$id])->fetchAll();
foreach($todo as $t){$message=$t['invoice_status']==='draft'?'Invoice '.e($t['invoice_number']).' needs to be created from your reviewed agreement.':($t['invoice_status']?'Invoice '.e($t['invoice_number']).' is ready in My invoices.':'Review the agreement to create your invoice.');echo '<div class="alert alert-warning d-flex flex-wrap justify-content-between align-items-center gap-2">'.e($t['agreement_number']).' · '.$message.'<a class="btn btn-sm btn-accent" href="'.BASE.'shared/agreement.php?id='.$t['agreement_id'].'">Open agreement</a></div>';}
echo '<div class="row g-3 mb-4">';
kpi('Reservations',one('SELECT COUNT(*) FROM reservations WHERE customer_id=?',[$id]),'calendar-check','my.php?tab=res');
kpi('Upcoming trips',one("SELECT COUNT(*) FROM reservations WHERE customer_id=? AND status IN('pending','confirmed') AND return_datetime>NOW()",[$id]),'signpost-2');
kpi('Outstanding balance',money(one("SELECT COALESCE(SUM(outstanding_balance),0) FROM vw_invoice_balances WHERE customer_id=? AND status NOT IN('void','draft')",[$id])),'receipt','my.php?tab=inv');
kpi('Total paid',money(one("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN invoices i USING(invoice_id) WHERE i.customer_id=? AND p.status IN('completed','partially_refunded')",[$id])),'credit-card','my.php?tab=pay');
echo '</div><div class="row g-4"><div class="col-lg-7">';
panel('My recent reservations',['Code','Vehicle','Pickup','Status'],array_map(fn($x)=>[e($x['reservation_code']),e($x['make'].' '.$x['model']),e($x['pickup_datetime']),badge($x['status'])],q('SELECT r.*,v.make,v.model FROM reservations r JOIN vehicles v USING(vehicle_id) WHERE r.customer_id=? ORDER BY r.created_at DESC LIMIT 5',[$id])->fetchAll()),'my.php?tab=res','You have no reservations yet.');
echo '</div><div class="col-lg-5">';
panel('Recent payments',['Payment','Amount','Status'],array_map(fn($x)=>[e($x['payment_number']),money($x['amount']),badge($x['status'])],q('SELECT p.* FROM payments p JOIN invoices i USING(invoice_id) WHERE i.customer_id=? ORDER BY p.payment_id DESC LIMIT 5',[$id])->fetchAll()),'my.php?tab=pay','No payments yet.');
echo '</div></div>';foot();
